let LANG = null;
try { LANG = localStorage.getItem('biblio.lang'); } catch {}
if (!LANG) LANG = (navigator.language || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
if (!['fr', 'en'].includes(LANG)) LANG = 'fr';
function t(key) {
  const d = I18N[LANG] || I18N.fr;
  return d[key] || I18N.fr[key] || key;
}
function setLang(lang) {
  LANG = lang;
  try { localStorage.setItem('biblio.lang', lang); } catch {}
  applyI18n();
}
/* Bascule langue — globale, appelable en inline onclick (robuste mobile) */
(globalThis.__toggleLang = function () {
  try {
    const nl = LANG === 'fr' ? 'en' : 'fr';
    setLang(nl);
    if (typeof renderAll === 'function') renderAll();
    if (typeof toast === 'function') toast(nl === 'fr' ? 'Langue : Français' : 'Language: English', 4000);
    return true;
  } catch (e) {
    try { alert('Lang error: ' + e.message); } catch {}
    return false;
  }
});

function applyI18n() {
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const k = el.getAttribute('data-i18n');
    const v = t(k);
    if (k.endsWith('_title')) el.setAttribute('title', v);
    else if (k.endsWith('_placeholder')) el.setAttribute('placeholder', v);
    else el.innerHTML = v;
  });
  document.documentElement.setAttribute('lang', LANG);
}

