function tm(key, ...args) {
  const m = MSGS[key];
  if (!m) return key;
  const tpl = LANG === 'en' ? m[1] : m[0];
  if (!args.length) return tpl;
  return tpl.replace(/\{\{?(\d+)\}?\}/g, (_, n) => args[+n - 1] ?? '');
}
